struct Data {
    value: i32,
}

fn main() {
    let mut data = Data { value: 10 };

    // Immutable borrow
    let ref_imm = &data.value;
    assert_eq!(*ref_imm, 10);

    // Mutable borrow (must happen after immutable borrow ends)
    {
        let ref_mut = &mut data.value;
        *ref_mut = 20;
    } // Mutable borrow ends here

    // Re-borrow immutably after mutable borrow ends
    let ref_imm2 = &data.value;
    assert_eq!(*ref_imm2, 20);

    // Attempting to use the original immutable borrow ref_imm here would cause a compile error,
    // but since we are in a new scope and ref_imm is no longer valid, we can safely proceed.
    // The original ref_imm is dropped at the end of its scope.

    println!("PASS");
}
